n29866.content:
\begin{definition}
  \label{def:partial-application}
  %
  \lean{PartialApplication}
  \leanok
  %
  A \emph{partial application} on a set $A$ is a map ${-} \cdot_A {-} : \widetilde{A} \times \widetilde{A} \to \widetilde{A}$.
\end{definition}

n29867.content:
\begin{definition}
  \label{def:PCA}
  %
  \leanok
  \lean{PCA}
  \uses{def:partial-application}
  %
  A set $A$ with a partial map ${-} \cdot_A {-}$ is a \emph{partial combinatory algebra (PCA)} if there are
  elements $\mathsf{K}, \mathsf{S}\in \widetilde{A}$ such that, for all $u, v, w \in \widetilde{A}$:
  %
  \begin{align*}
    &K\,{\Downarrow}, &
    &S\,{\Downarrow},\\
    &u\,{\Downarrow} \Rightarrow\mathsf{K}\, u\,{\Downarrow}, &
    &u\,{\Downarrow} \Rightarrow\mathsf{S}\, u\,{\Downarrow}, \\
    &u\,{\Downarrow} \land v\,{\Downarrow} \Rightarrow\mathsf{K}\, u \, v\,{\Downarrow}, &
    &u\,{\Downarrow} \land v\,{\Downarrow} \Rightarrow\mathsf{S}\, u \, v\,{\Downarrow}, \\
    &u\,{\Downarrow} \land v\,{\Downarrow} \Rightarrow\mathsf{K}\, u \, v = u, &
    &u\,{\Downarrow} \land v\,{\Downarrow} \land w\,{\Downarrow} \Rightarrow\mathsf{S}\, u \, v \, w\,{\Downarrow}, \\
    &&
    &u\,{\Downarrow} \land v\,{\Downarrow} \land w\,{\Downarrow}
     \Rightarrow\mathsf{S}\, u \, v \, w = (u \, w) \, (v \, w), \\
  \end{align*}
\end{definition}

n29868.content:
\begin{definition}
  \label{def:expression}
  %
  \leanok
  \lean{PCA.Expr}
  %
  Given a set $\Gamma$ of \emph{variables} and a set $A$ of elements, the
  \emph{expressions} $\mathsf{Expr}\,\Gamma \,A$ are generated inductively by the following clauses:
  %
  \begin{itemize}
    \item the constants $\mathtt{K}$ and $\mathtt{S}$ are expressions,
    \item an element $a \in A$ is an expression,
    \item a variable $x \in \Gamma$ is an expression,
    \item if $e_1$ and $e_2$ are expressions then $e_1 \cdot e_2$ is an expression.
  \end{itemize}
\end{definition}

n29869.content:
\begin{definition}
  \label{def:override}%
  \leanok
  \lean{PCA.override}
  %
  Given a valuation $\eta : \Gamma \to A$, $x \in A$ and $a \in a$, we may \emph{override} $\eta$
  to get a valuation $\eta [x \mapsto a] : \Gamma \to A$ such that
  %
  \begin{equation*}
    (\eta [x \mapsto a]) y =
    \begin{cases}
      \eta(y) &\text{if $y \in \Gamma$,}\\
      a       &\text{if $y = x$.}
    \end{cases}
  \end{equation*}
\end{definition}

n29870.content:
\begin{definition}
  \label{def:evaluation}
  %
  \leanok
  \lean{PCA.eval}
  %
  \uses{def:expression, def:PCA}
  %
  The \emph{evaluation} $[\![ e ]\!] \, \eta$ of an expression $e \in \mathsf{Expr}\,\Gamma \,A$ in a PCA~$A$ at a
  valuation $\eta : \Gamma \to A$ is defined recursively by the clauses
  %
  \begin{align*}
    [\![ \mathsf{K}]\!] \, \eta &= \mathsf{K}\\
    [\![ \mathsf{S}]\!] \, \eta &= \mathsf{K}\\
    [\![ a ]\!] \, \eta &= a  &&\text{if $a \in A$}\\
    [\![ x ]\!] \, \eta &= \eta(x)  &&\text{if $x \in \Gamma$}\\
    [\![ e_1 \cdot e_2 ]\!] \, \eta &= ([\![ e_1 ]\!] \, \eta) \cdot_A ([\![ e_2 ]\!] \, \eta).
  \end{align*}
\end{definition}

n29871.content:
\begin{definition}
  \label{def:expression-defined}
  %
  \leanok
  \lean{PCA.defined}
  \uses{def:expression, def:evaluation}
  %
  An expression $e \in \mathsf{Expr}\,\Gamma \,A$ is \emph{defined} when $[\![ e ]\!] \, \eta\,{\Downarrow}$
  for all $\eta : \Gamma \to A$.
\end{definition}

n29872.content:
\begin{definition}
  \label{def:abstraction}
  %
  \leanok
  \lean{PCA.abstr}
  \uses{def:expression, def:override, def:PCA}
  %
  The \emph{abstraction} of an expression $e \in \mathsf{Expr}\,\Gamma \,A$ 
  with respect to a variable $x \in \Gamma$
  is the expression $\langle x \rangle\, e \in \mathsf{Expr}\,\Gamma \,A$ defined recursively by
  %
  \begin{align*}
    \langle x \rangle\, x &= \mathsf{S}\cdot \mathsf{K}\cdot \mathsf{K}, \\
    \langle x \rangle\, y &= \mathsf{K}\cdot y &&\text{if $x \neq y \in \Gamma$}, \\
    \langle x \rangle\, a &= \mathsf{K}\cdot a &&\text{if $a \in A$}, \\
    \langle x \rangle\, (e_1 \cdot e_2) &= \mathsf{S}\cdot (\langle x \rangle\, e_1) \cdot (\langle x \rangle\, e_2).
  \end{align*}
\end{definition}

n29873.content:
\begin{proposition}
  \label{prop:abstraction-defined}
  %
  \leanok
  \lean{PCA.df_abstr}
  \uses{def:expression-defined, def:abstraction}
  %
  An abstraction $\langle x \rangle\, e$ is defined.
\end{proposition}

n29875.content:
\begin{proposition}
  \label{prop:abstraction-equal}
  %
  \leanok
  \lean{PCA.eval_abstr}
  \uses{def:expression, def:evaluation, def:abstraction, def:override}
  %
  Let $x \in \Gamma$ and $e \in \mathsf{Expr}\,(\Gamma \cup \{x\})\,A$.
  Then for every $a \in A$ and $\eta : \Gamma \to A$
  %
  \begin{equation*}
    [\![ (\langle x \rangle\, e) \cdot a ]\!] \, \eta =
    [\![ e ]\!] \, \eta[x \mapsto a].
  \end{equation*}
\end{proposition}

n29877.content:
\begin{definition}[Identity]
  \label{def:combinator-I}
  \lean{PCA.I, PCA.eq_I}
  \leanok
  \uses{def:PCA}
  %
  There is the \emph{identity combinator} $\mathsf{I} \in A$ such that $I \, a = a$ for all $a \in A$.
\end{definition}

n29878.content:
\begin{definition}[Pairing]
  \label{def:combinator-pairing}
  \uses{def:PCA}
  \lean{PCA.pair, PCA.fst, PCA.snd, PCA.eq_fst_pair, PCA.eq_snd_pair}
  \leanok
  %
  There are combinators $\mathsf{pair}, \mathsf{fst}, \mathsf{snd} \in A$ such that, for all $a, b \in A$,
  %
  \begin{align*}
    \mathsf{fst}\, (\mathsf{pair}\,a\,b) &= a,
    &
    \mathsf{snd}\, (\mathsf{pair}\,a\,b) &= b.
  \end{align*}
\end{definition}

n29879.content:
\begin{definition}[Booleans]
  \label{def:combinator-bool}
  \lean{PCA.ite, PCA.fal, PCA.tru, PCA.eq_ite_fal, PCA.eq_ite_tru}
  \uses{def:PCA}
  \leanok
  %
  There are combinators $\mathsf{ite} \, \mathsf{fal}, \mathsf{tru} \in A$ such that, for all $a, b \in a$,
  %
  \begin{equation*}
    \mathsf{ite} \, \mathsf{tru} \ ,a \, b = a
    \text{and}
    \mathsf{ite} \, \mathsf{fal} \, a \, b = b.
  \end{equation*}
\end{definition}

n29880.content:
\begin{definition}[Numerals]
  \label{def:combinator-nat}
  \lean{PCA.numeral, PCA.succ, PCA.primrec, PCA.eq_primrec_zero, PCA.eq_primrec_succ}
  \uses{def:PCA}
  \leanok
  %
  For each $n \in \mathbb{N}$ there is $\overline{n} \in A$, as well as combinators $\mathsf{succ}, \mathsf{primrec} \in A$
  such that, for all $n \in \mathbb{N}$ and $a, f \in A$,
  %
  \begin{align*}
    \mathsf{succ} \, \overline{n} &= \overline{n+1},
    \\
    \mathsf{primrec} \, a \, f \, \overline{0} &= a,
    \\
    \mathsf{primrec} \, a \, f \, \overline{n+1} &= f \, \overline{n} \, (\mathsf{primrec} \, a \, f \, \overline{n}).
  \end{align*}
\end{definition}

n29881.content:
\begin{definition}
  %
  \label{def:combinator-Y}
  \uses{def:PCA}
  \lean{PCA.Y, PCA.df_Y, PCA.eq_Y}
  \leanok
  %
  There is a combinator $\mathsf{Y} \in A$ such that, for all $a \in A$,
  %
  \begin{equation*}
    \mathsf{Y} \, a = a (\mathsf{Z} \, a).
  \end{equation*}
\end{definition}

n29882.content:
\begin{definition}[General recursion]
  %
  \label{def:combinator-Z}
  \uses{def:PCA}
  \lean{PCA.Z, PCA.df_Z, PCA.eq_Z}
  \leanok
  %
  There is a combinator $\mathsf{Z} \in A$ such that, for all $f, a \in A$,
  %
  \begin{equation*}
    \mathsf{Z} \, f\,{\Downarrow},
    \qquad\text{and}\qquad
    \mathsf{Z} \, f \, a = f (\mathsf{Z} \, f) \, a.
  \end{equation*}
\end{definition}

n29883.content:
\begin{definition}
  \label{def:representable-function}
  \uses{def:PCA}
  %
  A partial map $f : A \rightharpoonup A$ is \emph{represented} by $a \in A$ when,
  for all $b \in B$, $f(b) = a \cdot b$.
\end{definition}

n29884.content:
\begin{theorem}
  \label{thm:recursive-map-representable}
  \uses{def:representable-function}
  Every general recursive map $f : \mathbb{N}\rightharpoonup\mathbb{N}$ is represented in the following sense:
  there is $a \in A$ such that, for all $n \in \mathbb{N}$, if $f(n)\,{\Downarrow}$ then $\overline{f(n)} = a \cdot \overline{n}$.
\end{theorem}

n29885.content:
\begin{definition}
  \label{def:CA}
  \lean{CA}
  \leanok
  %
  A \emph{(total) combinatory algebra (CA)} is given by a carrier set $A$ and a \emph{total} binary operation
  ${-} \cdot {-} : A \times A \to A$, such that there are $\mathsf{K}, \mathsf{S}$ satisfying the characteristic
  equations
  %
  \begin{equation*}
    \mathsf{K}\cdot x \cdot y = x
    \qquad\text{and}\qquad
    \mathsf{S}\cdot x \cdot y \cdot z = (x \cdot z) \cdot (y \cdot z).
  \end{equation*}
\end{definition}

n29886.content:
\begin{proposition}
  \label{prop:CAisPCA}
  \lean{CA.isPCA}
  \uses{def:CA, def:PCA}
  \leanok
  %
  Every combinatory algebra is a partial combinatory algebra.
\end{proposition}

n29887.content:
\begin{proof}
  \leanok
  Simply reuse the total application as the partial one.
\end{proof}

n29888.content:
\begin{definition}
  \label{def:FreeCA}
  \uses{def:CA}
  \lean{FreeCA}
  \leanok
  %
  The \emph{free combinatory algebra} is generated freely by the symbols $\mathsf{K}$ and $\mathsf{S}$ and formal binary application, quotiented by provable equality.
\end{definition}

n29889.content:
\begin{definition}
  \label{def:Listing}
  \lean{Listing}
  \leanok
  A \emph{listing} on a set $A$ is a section $\mathsf{fromList} : \mathsf{List}\,A \to A$ and a retraction $\mathsf{toList} : A \to \mathsf{List}\,A$.
\end{definition}

n29890.content:
\begin{definition}
  \label{def:graph-model-application}
  \uses{def:Listing}
  \lean{GraphModel.apply}
  \leanok
  The \emph{application} ${-} \cdot {-} : \mathcal{P}\,A \times \mathcal{P}\,A \to \mathcal{P}\,A$ is defined by
  %
  \begin{equation*}
    S \cdot T = \{x \in A \mid\exists y \in A.\, \mathsf{toSet}\,y \subseteq T \land \langle x,y \rangle \in S\}.
  \end{equation*}
\end{definition}

n29891.content:
\begin{theorem}
  \label{thm:graph-model}
  \uses{def:graph-model-application, def:CA}
  \lean{GraphModel.isCA}
  \leanok
  The set $\mathcal{P}\,A$ with the application as above is a combinatory algebra.
\end{theorem}
